inputs = ['kv', 'ez', 'wvc', 'ae', 'dywwie']
outputs = ['kzx', 'ezx', 'wzxk', 'xue', 'dywwie']

# Analyze each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Transforming '{inp}' to '{outp}':")
        # Find where differences occur
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append(j)

        # Check if it's insertion/deletion/substring replacement
        if len(outp) > len(inp):
            # Insertion case
            print(f"  Insertion detected (output longer)")
            # Look for where extra character appears
            for j in range(len(inp)):
                if j >= len(outp) or inp[j] != outp[j]:
                    print(f"  Inserted '{outp[j]}' at position {j}")
                    break
        elif len(outp) < len(inp):
            # Deletion case  
            print(f"  Deletion detected (output shorter)")
        else:
            # Same length - substitution
            print(f"  Substitution detected")
        print()

